-- Generated from content/web-novel/peta-langit-yang-retak.mjs. Run node scripts/build-web-novel-seed.mjs to regenerate.
-- Idempotent: an existing slug is left untouched, including reader progress and editorial changes.
do $novel_seed$
declare
  v_data jsonb := $novel_data${"slug":"peta-langit-yang-retak","title":"Peta Langit yang Retak","tagline":"Satu pintu membawanya ke dunia lain. Pulang mungkin berarti menghapus dunia itu.","description":"Mira tersesat dari lift apartemennya ke Lentara, dunia yang langitnya dijahit dari ingatan. Bersama seorang kurir muda dan peta yang hidup, ia mencari jalan pulang sebelum retakan langit menelan dua dunia. Setiap jalur membuka rahasia berbeda dan membawanya pada satu dari tiga akhir.","episodes":["Pintu yang Salah","Peta dan Ingatan","Langit yang Terkoyak","Harga Sebuah Pulang","Tiga Fajar"],"chapters":[{"number":1,"key":"pintu-lantai-tiga-belas","title":"Pintu Lantai Tiga Belas","synopsis":"Lift yang biasa membawa Mira pulang berhenti di lantai yang tak pernah ada.","body":"Mira pulang membawa sekotak kue ulang tahun yang belum sempat diberikan kepada ibunya. Di lift apartemen, angka dua belas padam, lalu angka tiga belas menyala di tempat yang sebelumnya hanya berupa logam polos. Ketika pintu terbuka, bau hujan dan rumput basah masuk bersama cahaya berwarna tembaga. Di luar bukan koridor apartemen, melainkan jembatan batu yang menggantung di antara dua tebing.\n\nDi langit ada garis hitam tipis, seperti kertas yang hampir sobek. Seorang anak berseragam kurir berlari melewatinya dan berhenti ketika melihat kotak kue. \"Kau datang dari sisi yang belum digambar,\" katanya. Namanya Tavi. Ia menyelipkan tiket kereta bercap bulan ke tangan Mira. Jauh di bawah jembatan, lentera kota berkelip; di arah lain, peluit kereta terdengar dari hamparan abu. Pintu lift menutup di belakangnya tanpa tombol untuk memanggilnya kembali.","choices":[["kota-di-balik-hujan","Ikuti Tavi menuju kota"],["stasiun-abu","Cari kereta di hamparan abu"]]},{"number":2,"key":"kota-di-balik-hujan","title":"Kota di Balik Hujan","synopsis":"Mira memasuki kota yang menukar arah jalan setiap kali hujan turun.","body":"Kota Lentara berdiri di bawah hujan yang jatuh ke atas. Tavi menyuruh Mira mengingat warna atap, bukan nama jalan: setiap rintik akan memindahkan gang ke tempat lain. Mira menandai tiang-tiang biru dengan remah kue, tetapi remah itu justru melayang menjadi kunang-kunang kecil. Dunia ini tampaknya menolak benda yang dibawa dari rumah.\n\nDi pasar, seorang perempuan tua menjaga jam tanpa jarum. Di seberang jalan, gedung arsip membuka pintunya hanya setiap hujan berhenti. Tavi mengatakan bahwa keduanya tahu tentang Peta Pulang, benda yang dapat menggambar jalan antara dunia. Ia tidak mengatakan mengapa suaranya bergetar ketika menyebut peta itu. Mira menyimpan tiket kereta di saku dan memutuskan siapa yang lebih dulu dapat dipercaya.","choices":[["penjaga-pasar","Tanya penjaga pasar"],["arsip-tanpa-nama","Masuk ke gedung arsip"]]},{"number":3,"key":"stasiun-abu","title":"Stasiun Abu","synopsis":"Kereta datang tanpa rel dan membawa penumpang yang melupakan tujuan mereka.","body":"Abu di tanah berputar ketika sebuah kereta muncul dari kabut, roda-rodanya tidak menyentuh apa pun. Tiket di tangan Mira menjadi hangat. Kondektur menerima tiket itu, tetapi bertanya tujuan dengan bahasa yang tidak dikenalnya. Mira menyebut \"rumah\"; huruf-huruf pada tiket berubah menjadi gambar dua pintu yang saling membelakangi.\n\nDi bangku belakang duduk seorang perempuan yang terus menulis namanya sendiri di telapak tangan agar tidak lupa. Ia menyebut dirinya Sera, mantan penjaga arsip. Kereta berikutnya menuju utara, kata Sera, tetapi kota terdekat memiliki arsip tentang setiap pelintas dunia. Mira dapat turun dan mencari penjelasan, atau bertahan di gerbong untuk melihat sumber retakan langit. Di jendela, bayangan ibunya tampak sesaat lalu hilang.","choices":[["arsip-tanpa-nama","Turun dan cari arsip"],["kereta-ke-utara","Tetap di kereta ke utara"]]},{"number":4,"key":"penjaga-pasar","title":"Penjaga Pasar","synopsis":"Sebuah jam tanpa jarum menunjukkan sesuatu yang tidak bisa dibaca oleh waktu.","body":"Perempuan penjaga pasar bernama Ibu Osa. Ia memutar jam tanpa jarum itu ke arah Mira, dan di balik kacanya terlihat lift apartemen yang kosong. \"Pintu asalmu belum hilang,\" katanya, \"tetapi kedua sisinya tidak lagi tiba pada waktu yang sama.\" Ia menukar satu petunjuk dengan sepotong kue. Mira menyerahkan bagian yang tadinya untuk ibunya; rasanya berubah menjadi buah yang belum pernah ia kenal.\n\nOsa menunjukkan bekas tinta di telapak Mira. Garis-garis tipis bergerak mengikuti denyut nadi, membentuk jalan yang belum pernah ia tempuh. Peta Pulang, rupanya, sedang menggambar dirinya melalui setiap pilihan. Osa menyuruhnya menemui pembuat peta di rumah beratap merah sebelum para pemburu nama mengetahui keberadaannya. Untuk pertama kalinya sejak lift terbuka, Mira merasa perjalanan ini memiliki arah.","choices":[["peta-bernapas","Cari rumah beratap merah"]]},{"number":5,"key":"arsip-tanpa-nama","title":"Arsip Tanpa Nama","synopsis":"Catatan pelintas dunia menyebut harga yang harus dibayar untuk pulang.","body":"Lemari arsip menjulang hingga tertutup kabut di dalam ruangan. Pada laci bertanda \"Pengunjung dari Bumi\", Mira menemukan ratusan kartu tanpa nama. Setiap kartu memiliki satu kalimat terakhir: aku pulang, tetapi lupa siapa yang menunggu. Sera, yang tiba melalui pintu samping, menjelaskan bahwa arsip menyimpan akibat dari perjalanan, bukan perjalanan itu sendiri.\n\nDi meja penjaga terletak peta kosong yang bergerak setiap kali Mira mengingat suara ibunya. Sera menyuruhnya membawa peta kepada pembuatnya. Namun sebuah kartu lain memuat tulisan tangan Mira, padahal ia belum pernah ke Lentara. Pada kartu itu hanya ada satu kata: \"jangan bayar dengan nama.\" Mira bisa mengejar asal peta atau terlebih dahulu mencari arti peringatan tersebut. Di luar, retakan langit bertambah satu ruas.","choices":[["peta-bernapas","Ikuti petunjuk peta"],["harga-sebuah-nama","Selidiki peringatan nama"]]},{"number":6,"key":"kereta-ke-utara","title":"Kereta ke Utara","synopsis":"Di utara, penduduk desa hidup di halaman dunia yang terlipat.","body":"Kereta melintasi ladang yang berganti musim pada setiap jendela. Tavi muncul di gerbong makanan, basah kuyup dan marah karena Mira meninggalkannya. Ia tidak meminta maaf atas sikapnya tadi. Ia hanya memberikan selembar peta kecil, robek di tengah, lalu berkata bahwa kereta akan melewati desa asalnya.\n\nKetika mereka tiba, rumah-rumah desa tampak berdiri di dua sisi satu jalan yang sama. Setiap orang yang menyeberang menghilang sesaat dan muncul dengan usia berbeda. Seorang penjaga menara menawarkan perlindungan jika Mira langsung menuju bangunan di bukit; Tavi meminta mereka turun untuk menolong warga sebelum pintu desa menutup. Mira melihat retakan di langit tepat di atas menara. Kedua jalan menjanjikan jawaban, tetapi tidak jawaban yang sama.","choices":[["desa-yang-terlipat","Turun bersama Tavi"],["menara-musim","Naik ke menara di bukit"]]},{"number":7,"key":"peta-bernapas","title":"Peta Bernapas","synopsis":"Peta hidup mengingat jalan yang tidak pernah dilewati Mira.","body":"Pembuat peta itu bukan manusia, melainkan meja kayu tua yang menghela napas setiap kali disentuh. Di atasnya, tinta membentuk garis dari kota, stasiun, dan tempat-tempat yang belum dikenal Mira. Sera berkata meja itu terbuat dari pohon yang tumbuh di celah antara dua dunia. Karena itu ia dapat menunjukkan jalan pulang, tetapi selalu menggambar harga di bagian belakang kertas.\n\nMira membalik peta. Di sana terlihat sebuah danau sebagai mata, menara sebagai jarum, dan tiga matahari kecil di tepinya. Tulisan yang muncul perlahan berbunyi: jalan pulang tidak dapat dimiliki seorang diri. Tavi ingin membakar peta sebelum para pemburu nama merebutnya. Mira justru melipatnya dan memasukkannya ke saku; jika jawabannya ada di danau, mereka harus melihat sendiri apa yang dipantulkan air itu.","choices":[["danau-cermin","Datangi danau pada peta"]]},{"number":8,"key":"harga-sebuah-nama","title":"Harga Sebuah Nama","synopsis":"Mira mengetahui mengapa para pelintas dunia kehilangan identitas.","body":"Di ruang bawah arsip, nama-nama disimpan dalam botol kaca. Sera membuka satu botol kosong dan menunjukkan bekas sidik jari di lehernya. Dahulu ia membantu para pelintas pulang dengan menukar nama mereka untuk menjaga pintu tetap terbuka. Ia berhenti ketika menyadari dunia tujuan juga ikut kehilangan sesuatu: orang-orang yang menunggu tidak lagi ingat siapa yang mereka tunggu.\n\nPada rak tertinggi terdapat botol bertuliskan Mira, tetapi isinya cahaya, bukan nama. Sera bersikeras botol itu belum pernah dibuka. Di luar ruangan, seseorang berbisik dari balik pintu, menyebut alamat apartemen Mira dengan tepat. Jika ia mengejar suara itu, mungkin ia akan menemukan saksi dari Bumi. Jika ia membawa botol ke danau, airnya mungkin menjelaskan mengapa namanya sudah tercatat sebelum kedatangannya.","choices":[["danau-cermin","Bawa botol ke danau"],["saksi-dari-bumi","Kejar suara dari Bumi"]]},{"number":9,"key":"desa-yang-terlipat","title":"Desa yang Terlipat","synopsis":"Tavi memperlihatkan rumah yang hanya muncul sekali dalam dua hari.","body":"Tavi menuntun Mira melewati jalan yang sama tiga kali. Pada langkah keempat, sebuah rumah kecil muncul di antara dua pohon apel. Ibunya pernah tinggal di sana sebelum retakan pertama, katanya. Kini rumah itu muncul setiap kali desa mengingat musim panas. Di meja makan masih ada dua mangkuk. Tavi tidak menyentuh salah satunya.\n\nAnak-anak desa menggambar langit dengan garis jahitan. Mereka mengatakan seseorang di menara sedang mencuri musim agar retakan tidak meluas, tetapi setiap musim yang diambil membuat satu kenangan warga menghilang. Tavi ingin naik untuk menghentikannya. Mira mendengar peluit kereta dari arah berlawanan dan melihat seorang penumpang yang berbicara dengan logat kotanya sendiri. Mereka harus memilih antara menyelidiki menara atau mengejar satu-satunya orang lain yang mungkin tahu jalan pulang.","choices":[["saksi-dari-bumi","Temui penumpang dari Bumi"],["menara-musim","Selidiki penjahit musim"]]},{"number":10,"key":"danau-cermin","title":"Danau Cermin","synopsis":"Air memperlihatkan dua dunia yang saling menekan dari sisi berlawanan.","body":"Danau itu tenang meski hujan turun. Pada permukaannya, Mira melihat dapur apartemen: ibunya meniup lilin kecil di atas kue pengganti. Di balik pantulan lain, Lentara tampak seperti selembar kain yang ditahan oleh ribuan benang cahaya. Setiap kali Mira mendekat, satu benang bergetar mengikuti suaranya.\n\nSeorang penjaga danau mengatakan bahwa retakan tidak disebabkan kedatangan Mira. Dua dunia sudah terlalu lama berbagi pintu tanpa memahami akibatnya. Namun orang dari sisi lain dapat memilih cara pintu itu ditutup atau dijaga. Di dasar air terlihat kunci pertama, sementara di tepi danau Tavi menawarkan janji: jangan biarkan satu dunia selamat dengan menghapus dunia lain. Mira meraih tangan Tavi, atau masuk sendiri mencari kunci yang berkilat.","choices":[["janji-di-tepi-air","Berjanji pada Tavi"],["kunci-pertama","Selam mencari kunci"]]},{"number":11,"key":"saksi-dari-bumi","title":"Saksi dari Bumi","synopsis":"Pelintas lain membawa kabar tentang ibu Mira dan sebuah pilihan lama.","body":"Lelaki berjaket hujan yang memanggil Mira bernama Damar. Ia mengaku berasal dari kota yang sama dan pernah melewati pintu tiga belas setahun lalu. Ia membawa foto ibunya Mira berdiri di depan gedung apartemen. Foto itu baru diambil kemarin. Ibunya tidak berhenti mencari; setiap petang ia masih menunggu di lobi, berharap lift terbuka di lantai yang salah.\n\nDamar mengatakan ia memilih pulang, tetapi kembali terseret ke Lentara karena pintu itu tidak pernah benar-benar ditutup. Ia menyimpan sebuah surat yang gagal dikirim dan pecahan kunci yang terasa dingin saat didekatkan ke peta Mira. Daripada percaya semua ucapannya, Mira bisa memeriksa pecahan itu pada penjaga danau. Namun surat untuk ibunya mungkin lebih mendesak daripada teka-teki dunia yang baru dikenalnya.","choices":[["kunci-pertama","Periksa pecahan kunci"],["surat-untuk-ibu","Baca surat yang gagal dikirim"]]},{"number":12,"key":"menara-musim","title":"Menara Musim","synopsis":"Pencurian musim ternyata menahan retakan agar tak jatuh ke desa.","body":"Di puncak menara, empat jam dinding menunjukkan musim yang berbeda. Penjaganya, seorang penjahit langit bernama Ruun, menarik benang emas dari jarum raksasa. Setiap tarikan membuat salju di luar berubah menjadi hujan, lalu menjadi bunga. Ia terlihat kelelahan, bukan kejam. Jika berhenti, katanya, retakan akan membelah desa sebelum malam.\n\nRuun tidak menyangkal bahwa ingatan warga ikut tercabut. Ia menunjukkan buku kecil berisi nama-nama yang berhasil ia selamatkan dari kelupaan. Nama ibu Tavi ada di halaman terakhir, dicoret dua kali lalu ditulis kembali. Mira melihat satu gulungan benang menuju ruang kerja tersembunyi dan gulungan lain ke stasiun kereta. Ia dapat belajar menjahit langit bersama Ruun atau mengikuti jalur benang yang mencuri musim itu dari sumbernya.","choices":[["penyulam-langit","Belajar pada Ruun"],["musim-yang-dicuri","Ikuti asal benang musim"]]},{"number":13,"key":"janji-di-tepi-air","title":"Janji di Tepi Air","synopsis":"Mira dan Tavi menyepakati satu syarat sebelum melangkah lebih jauh.","body":"Tavi tidak meminta Mira tinggal di Lentara. Ia hanya ingin Mira melihat seluruh akibat sebelum memilih rumahnya sendiri. Mereka duduk di tepi danau, membagi sisa kue yang tak pernah habis sepenuhnya. Mira bercerita tentang ibunya, tentang janji makan malam yang gagal, dan rasa bersalah yang semakin berat setiap kali langit Lentara retak. Tavi bercerita tentang rumah yang muncul selang sehari dan ibunya yang lupa jalan pulang.\n\nDi air, peta memperlihatkan aula tempat empat penjuru Lentara berunding. Penjaga danau berkata kesaksian seseorang dari Bumi akan memberi mereka hak bicara. Mira menuliskan janjinya pada belakang tiket kereta: ia tidak akan membayar pintu dengan ingatan orang lain. Tulisan itu menyala, mengubah tiket menjadi undangan menuju sidang.","choices":[["sidang-empat-penjuru","Bawa janji ke sidang"]]},{"number":14,"key":"kunci-pertama","title":"Kunci Pertama","synopsis":"Kunci tidak membuka pintu; ia membuka ingatan tentang siapa yang membuatnya.","body":"Kunci dari danau tidak punya gigi. Ketika Mira menggenggamnya, ia melihat tukang jam dari Bumi bekerja bersama penjahit Lentara pada suatu musim yang tak tercatat. Mereka membuat pintu agar dua dunia dapat saling menolong saat bencana. Pintu itu berfungsi, tetapi tiap perjalanan mengambil sedikit ruang dari langit Lentara. Tidak ada penjahat tunggal di awal kisah ini, hanya niat baik yang tidak menghitung harga.\n\nDi sisi kunci terukir dua arah. Arah pertama menunjuk aula sidang, tempat keputusan bersama mungkin dibuat. Arah kedua menuju pintu di bawah kota, tempat mesin lama masih bekerja tanpa penjaga. Sera memperingatkan bahwa mematikan mesin terlalu cepat akan mengunci orang-orang yang sedang berada di sisi yang salah. Mira harus memilih siapa yang lebih dulu ia dengar: para pemimpin atau suara mesin itu sendiri.","choices":[["sidang-empat-penjuru","Tunjukkan kunci pada sidang"],["pintu-bawah-tanah","Periksa mesin pintu lama"]]},{"number":15,"key":"surat-untuk-ibu","title":"Surat untuk Ibu","synopsis":"Sepucuk surat membuat jalan pulang terasa dekat sekaligus mustahil.","body":"Surat Damar ditulis pada kertas resep dari dapur Mira. \"Aku masih mencari tombolnya,\" tulis ibunya. \"Kalau kau bisa membaca ini, jangan merasa harus pulang sendirian.\" Mira membaca kalimat itu berkali-kali hingga tinta di ujung kata menjadi buram. Damar mengakui ia pernah bertemu ibunya lewat celah pintu, tetapi tidak sanggup membawa kabar buruk bahwa setiap percobaan pulang memperlebar retakan.\n\nSurat itu menyimpan jadwal kereta terakhir sebelum gerhana. Jika Mira naik, ia mungkin dapat mencapai terminal yang menghadap Bumi. Namun Damar juga menggambar simbol penjahit langit pada amplop, petunjuk bahwa Ruun mengetahui cara membuat pintu bertahan tanpa mencuri nama. Mira melipat surat, menyimpannya dekat dada, dan memutuskan jawaban mana yang dikejar lebih dahulu.","choices":[["penyulam-langit","Temui penjahit langit"],["kereta-terakhir","Kejar kereta terakhir"]]},{"number":16,"key":"penyulam-langit","title":"Penyulam Langit","synopsis":"Ruun menawarkan cara menambal langit dengan persetujuan, bukan paksaan.","body":"Ruun membentangkan kain langit di meja. Setiap benang berasal dari satu kenangan yang diberikan dengan sukarela. Warga Lentara pernah melakukannya bersama, sebelum para pemimpin mulai mengambil musim secara diam-diam. Ia menunjukkan jahitan tua di sepanjang retakan: tidak indah, tetapi cukup kuat ketika semua orang mengingat alasannya.\n\nMira mencoba menjahit satu benang dari ingatannya tentang hujan di halte rumah. Jari-jarinya bergetar dan wajah ibunya sesaat memudar, lalu kembali ketika ia melepaskan jarum. Ruun berkata sebuah jahitan besar memerlukan kesaksian publik, atau sumber musim yang dicuri harus dikembalikan lebih dulu. Dari menara terlihat stasiun kereta menuju aula sidang dan gudang mesin yang menyimpan musim-musim hilang. Keduanya mungkin menolong, tetapi waktu sebelum gerhana semakin pendek.","choices":[["kereta-terakhir","Bawa usul ke kereta sidang"],["musim-yang-dicuri","Kembalikan musim yang dicuri"]]},{"number":17,"key":"sidang-empat-penjuru","title":"Sidang Empat Penjuru","synopsis":"Para pemimpin Lentara meminta Mira memilih pihak sebelum mendengar seluruh cerita.","body":"Aula sidang memiliki empat pintu dan tidak satu pun menghadap utara yang sama. Mira menceritakan lift, kunci, dan danau. Sebagian anggota dewan ingin menutup pintu ke Bumi malam itu juga. Sebagian lagi ingin mempertahankannya sebagai sumber ingatan baru, meski langit harus terus dijahit dengan musim yang dicuri. Tavi berdiri di belakang Mira, memegang tiket dengan janji yang sudah mereka tulis.\n\nSeorang putri tanpa mahkota menawarkan akses ke catatan pendiri; ia yakin ada perjanjian lama yang dilupakan dewan. Di sisi aula, seorang penjaga retakan mengangkat tangan berdarah dan berkata bahwa perjanjian apa pun tidak akan berguna jika langit runtuh sebelum pagi. Mira dapat mengejar bukti politik atau langsung mendengar orang yang menjaga luka itu setiap hari.","choices":[["putri-tanpa-mahkota","Baca catatan pendiri"],["penjaga-retakan","Dengar penjaga retakan"]]},{"number":18,"key":"pintu-bawah-tanah","title":"Pintu Bawah Tanah","synopsis":"Mesin tua masih membuka celah antar dunia tanpa ada yang mengendalikannya.","body":"Tangga di bawah kota turun melewati lapisan batu yang ditandai tahun-tahun hilang. Di dasarnya, mesin pintu berputar tanpa suara. Sebuah kursi kosong menghadap dua tuas: satu bertanda Rumah, satu bertanda Jaga. Mira menyentuh tuas pertama dan mendengar ibunya memanggil dari balik dinding. Tavi menariknya sebelum seluruh ruangan bergeser.\n\nPada panel mesin ada catatan pembuatnya: pintu hanya aman jika kedua dunia boleh mengatakan tidak. Sejak para penjaga terakhir pergi, mesin mengartikan diam sebagai persetujuan. Mira menemukan ruang kendali waktu yang bisa menghentikannya untuk satu detik, cukup lama untuk meminta jawaban. Tetapi di rel bawah tanah kereta terakhir sudah lewat; mengejarnya mungkin lebih cepat daripada membongkar mesin. Pilihan itu menentukan dari mana ia akan melihat akhir retakan.","choices":[["penjaga-retakan","Cari penjaga mesin"],["ruang-detik-nol","Masuk ruang kendali waktu"]]},{"number":19,"key":"kereta-terakhir","title":"Kereta Terakhir","synopsis":"Kereta menuju perbatasan Bumi membawa penumpang yang ingin melupakan Lentara.","body":"Gerbong penuh orang dengan koper kecil dan mata yang menatap lantai. Kondektur mengumumkan bahwa kereta akan berhenti dua kali: di ruang detik nol dan di terminal pulang. Pada kursi depan, Damar memegang foto kota asalnya begitu erat hingga sudutnya robek. Ia belum memutuskan apakah akan naik sampai akhir atau turun untuk membantu orang lain.\n\nMira membaca surat ibunya di sela guncangan kereta. Ia menyadari kata \"sendirian\" digarisbawahi dua kali. Mungkin ibunya tahu bahwa pintu dapat dilewati bersama; mungkin ia hanya berharap Mira tak menanggung semuanya sendiri. Ketika lampu gerbong meredup, peta di saku Mira menggambar dua peron yang berbeda. Ia dapat turun ke ruang kendali dan mencoba memperlambat bencana, atau tetap duduk sampai pintu rumah terlihat.","choices":[["ruang-detik-nol","Turun ke ruang kendali"],["terminal-kembali","Tetap menuju terminal"]]},{"number":20,"key":"musim-yang-dicuri","title":"Musim yang Dicuri","synopsis":"Gudang mesin menyimpan panas, salju, dan ingatan warga dalam tabung kaca.","body":"Tabung-tabung kaca berderet seperti perpustakaan tanpa buku. Di dalamnya ada musim panas sebuah desa, salju pertama seorang anak, dan bau tanah setelah hujan. Ruun membuka satu tabung kecil. Di luar, seorang nenek tiba-tiba ingat lagu yang diajarkan putrinya. Mira paham bahwa mengembalikan musim bukan sekadar memperbaiki cuaca; setiap botol menyimpan bagian hidup seseorang.\n\nMengosongkan gudang sekaligus akan melepaskan beban ke langit yang sudah rapuh. Ruun mengusulkan urutan perlahan, tetapi gerhana kedua akan tiba sebelum pekerjaan selesai. Dari jendela gudang, Mira melihat terminal kereta dan pusat retakan yang memerah. Ia dapat membawa petunjuk tentang tabung ke terminal agar para pelintas membantu, atau naik bersama Ruun ke tempat gerhana akan menyentuh jahitan langit.","choices":[["terminal-kembali","Bawa musim ke terminal"],["gerhana-kedua","Hadapi gerhana bersama Ruun"]]},{"number":21,"key":"putri-tanpa-mahkota","title":"Putri Tanpa Mahkota","synopsis":"Catatan pendiri mengubah pertikaian politik menjadi janji yang bisa ditagih.","body":"Nama putri itu Aven, meski ia menolak gelar yang terus diberikan dewan. Ia menunjukkan gulungan perjanjian pertama, ditandatangani seorang pembuat jam dari Bumi dan empat penjaga Lentara. Mereka sepakat tak akan membuka pintu tanpa persetujuan kedua sisi. Seiring waktu, kalimat tentang persetujuan dihapus dari salinan publik. Para penerus menyebut penghapusan itu pengorbanan perlu; Aven menyebutnya kebohongan.\n\nMira membaca tanda tangan terakhir dan melihat nama keluarganya sendiri. Nenek buyutnya pernah menjadi salah satu penjaga pintu. Kedatangannya bukan ramalan, melainkan akibat mesin yang mengenali garis keluarga. Aven menawarkan sidang terbuka di depan warga dan para pelintas. Jika bukti dibacakan, setiap orang dapat memutuskan apa yang rela ia berikan untuk menambal langit. Mira membawa gulungan itu ke aula cahaya.","choices":[["perjanjian-cahaya","Bacakan perjanjian asli"]]},{"number":22,"key":"penjaga-retakan","title":"Penjaga Retakan","synopsis":"Orang yang menjaga luka langit meminta Mira melihat siapa yang selama ini membayar harganya.","body":"Penjaga bernama Elen membawa Mira ke atas tembok kota. Dari sana retakan tampak seperti sungai hitam yang mengalir di antara bintang. Setiap malam Elen menambal tepinya dengan ingatan sukarela miliknya sendiri. Ia sudah lupa wajah saudara perempuannya, tetapi masih ingat mengapa ia mulai menjaga: tak seorang pun boleh dipaksa menjadi jahitan.\n\nElen memperlihatkan dua alat. Lentera pertama dapat memanggil warga untuk membuat perjanjian baru. Pisau kedua dapat memutus mesin pintu, membebaskan orang yang terjebak di antara dunia namun memadamkan jalan pulang untuk sementara. Mira mendengar suara kereta dan teriakan dari peron bawah. Ia harus memilih antara mengumpulkan persetujuan sebanyak mungkin atau menolong yang terjebak sebelum detik berikutnya pecah.","choices":[["perjanjian-cahaya","Nyalakan lentera persetujuan"],["harga-kebebasan","Bantu lepaskan yang terjebak"]]},{"number":23,"key":"ruang-detik-nol","title":"Ruang Detik Nol","synopsis":"Satu detik yang dibekukan memperlihatkan akar persoalan kedua dunia.","body":"Di ruang kendali, waktu berhenti begitu Mira meletakkan kunci pada meja. Debu menggantung di udara, api membeku pada ujung sumbu, dan suara ibunya tiba tanpa jeda. Di dinding muncul gambar mesin dari sisi Bumi: sebuah lift yang setiap malam mencoba menjemput orang hilang. Mesin Lentara dan lift itu saling menarik; tak satu pun dapat berhenti selama yang lain terus memanggil.\n\nMira menemukan catatan suara dari pembuat pintu. Ia meminta penerusnya tidak memilih solusi sendirian. Bukalah ingatan yang pecah, katanya, lalu tunjukkan pada kedua dunia. Di lantai terdapat serpih kaca berisi catatan masa lalu, sementara tuas pembebas dapat melepaskan penumpang yang tersangkut. Detik beku akan habis saat ia menyentuh salah satunya.","choices":[["harga-kebebasan","Tarik tuas pembebas"],["pecahan-ingatan","Baca serpih ingatan"]]},{"number":24,"key":"terminal-kembali","title":"Terminal Kembali","synopsis":"Pintu pulang terlihat nyata, tetapi antrian menuju ke sana tidak bergerak.","body":"Terminal dibangun menyerupai stasiun kecil dari Bumi. Ada papan jadwal, bangku besi, dan mesin penjual minuman yang hanya mengeluarkan tiket kosong. Di ujung peron, Mira melihat lorong apartemennya. Ibunya berdiri di seberang kaca, tak dapat mendengar ketika Mira memanggil. Setiap upaya mendorong pintu membuat langit Lentara bergetar dan antrian memanjang.\n\nDamar mengatakan jalan pulang harus dibuka dari kedua sisi. Ia bersedia kembali ke lift dan meminta ibunya Mira berhenti menekan tombol selama satu malam, memberi kedua mesin waktu untuk bernapas. Mira dapat ikut menempuh jalan ke rumah agar pesannya sampai, atau naik ke pusat gerhana untuk menghentikan tarikan mesin dari Lentara. Tavi, yang baru tiba, tidak meminta Mira memilih dirinya. Ia hanya menunggu jawaban yang jujur.","choices":[["jalan-ke-rumah","Kirim pesan melalui pintu rumah"],["gerhana-kedua","Naik ke pusat gerhana"]]},{"number":25,"key":"gerhana-kedua","title":"Gerhana Kedua","synopsis":"Retakan membesar saat dua matahari Lentara saling menutup.","body":"Di atas menara, cahaya gerhana membuat bayangan setiap orang jatuh ke arah berbeda. Ruun menjahit secepat mungkin, Elen menahan tepi retakan, dan Tavi membagi tiket kosong kepada warga yang ingin membantu. Mira melihat lift apartemennya mengambang di sela awan. Di balik pintu, ibunya menunggu tanpa tahu bahwa satu langkah terburu-buru bisa merobek lantai di bawah mereka.\n\nPeta Pulang kini menggambar pusat retakan sebagai jantung yang berdetak. Arah menuju rumah masih ada, tetapi akan semakin sempit setelah gerhana penuh. Jika Mira berjalan ke jantung, ia mungkin dapat mengubah aturan pintu untuk semua orang. Jika ia mengambil jalan pulang sekarang, ia harus menemukan cara agar orang di sisi lain ikut menutup mesin. Peta tidak memilihkannya.","choices":[["jalan-ke-rumah","Dekati pintu rumah"],["jantung-lentara","Masuki pusat retakan"]]},{"number":26,"key":"perjanjian-cahaya","title":"Perjanjian Cahaya","synopsis":"Warga dan pelintas akhirnya mendapat suara dalam nasib pintu.","body":"Aven membacakan perjanjian asli di depan aula yang penuh sesak. Orang-orang terdiam saat mendengar bahwa pintu dahulu dibuat untuk bantuan timbal balik, bukan untuk mengambil musim. Seorang petani menawarkan ingatan tentang panen pertama; seorang pelintas dari Bumi menawarkan cara memperbaiki jam mesin. Tak seorang pun diminta memberikan apa yang tidak ia pahami.\n\nMira melihat cahaya dari benang-benang kecil itu berkumpul. Cukup untuk memperkuat langit sementara, belum cukup untuk menentukan hubungan kedua dunia selamanya. Aven menanyakan apakah perjanjian harus menjadi jembatan bersama atau berhenti pada penyelamatan hari ini. Di luar aula, pintu rumah dan pusat retakan sama-sama menunggu. Mira kini memiliki kesaksian banyak orang untuk dibawa ke pilihan terakhir.","choices":[["fajar-untuk-semua","Jadikan persetujuan jembatan baru"],["rumah-dua-pintu","Buka jalan pulang dengan aturan baru"]]},{"number":27,"key":"harga-kebebasan","title":"Harga Kebebasan","synopsis":"Membebaskan penumpang terjebak memberi Mira kesempatan melihat dua pihak sekaligus.","body":"Ketika tuas dilepas, belasan orang jatuh dari celah antara dunia. Seorang anak Lentara memeluk ayahnya yang berasal dari Bumi; seorang perempuan tua duduk di lantai dan baru sadar ia masih memegang koper dari sepuluh tahun lalu. Elen membantu mereka berdiri satu per satu. Tidak semua ingin pulang. Tidak semua ingin tinggal.\n\nMira mengerti mengapa pintu tak boleh ditutup atas nama semua orang tanpa bertanya. Namun langit tak bisa menunggu pertemuan panjang. Ia dapat membawa para saksi ke aula untuk membangun jembatan yang lebih adil, atau menyimpan pecahan ingatan mesin sebagai bukti teknis bagi orang-orang di kedua sisi. Tavi berkata kebebasan bukan pintu yang selalu terbuka, melainkan hak untuk mengetahui ke mana pintu itu menuju.","choices":[["fajar-untuk-semua","Ajak para saksi membuat jembatan"],["rumah-dua-pintu","Bawa bukti ke pintu rumah"]]},{"number":28,"key":"pecahan-ingatan","title":"Pecahan Ingatan","synopsis":"Ingatan para pembuat pintu mengungkap satu jalan yang belum dicoba.","body":"Dalam serpih kaca, Mira melihat nenek buyutnya menutup mesin untuk pertama kali. Ia tidak menghancurkan pintu; ia membaginya menjadi dua, memberi masing-masing dunia kunci dan hak untuk menolak. Setelah ia pergi, para penerus menyatukan kunci agar perjalanan lebih mudah. Kemudahan itulah yang pelan-pelan merobek langit.\n\nPecahan lain memperlihatkan ibunya Mira sebagai anak kecil, berdiri di depan lift yang sama. Ia sudah pernah melihat pintu tiga belas, tetapi kenangannya tertutup oleh mesin. Mira kini tahu pulang tidak harus berarti melupakan Lentara. Dua kunci dapat membuat perjalanan aman jika kedua sisi setuju. Namun menyusun kembali kunci itu mungkin menuntut seseorang menjaga nama-nama yang hilang. Ia dapat membawa rancangan ke rumah atau memilih tinggal sebagai penjaga ingatan.","choices":[["rumah-dua-pintu","Bawa rancangan dua kunci pulang"],["nama-yang-tinggal","Jaga nama yang hilang"]]},{"number":29,"key":"jalan-ke-rumah","title":"Jalan ke Rumah","synopsis":"Mira mendekati pintu apartemen sambil membawa seluruh pilihan yang telah dibuat.","body":"Lorong apartemen semakin jelas. Lampu yang berkedip, karpet lusuh, dan bau sabun cucian membuat dada Mira sesak. Ia melihat ibunya tertidur di kursi lobi dengan jaket masih terpasang. Kue ulang tahun di tangan Mira sudah berubah rasa berkali-kali, tetapi kotaknya belum penyok. Ia ingin berlari dan memeluk ibunya sebelum pintu berubah pikiran.\n\nDi kaca, Tavi tampak di belakang Mira bersama orang-orang yang ia temui. Retakan langit mereka tercermin di jendela apartemen. Mira sadar ia tidak dapat menyembunyikan Lentara di balik cerita mimpi. Ia harus membawa rancangan dua pintu agar pulang menjadi pilihan aman, atau kembali ke jantung retakan untuk memastikan Lentara bertahan meski ia kehilangan kesempatan malam ini. Ia meletakkan telapak di kaca dan menunggu jawaban dari kedua sisi.","choices":[["rumah-dua-pintu","Bangun dua pintu yang saling setuju"],["nama-yang-tinggal","Kembali menjaga Lentara"]]},{"number":30,"key":"jantung-lentara","title":"Jantung Lentara","synopsis":"Di inti retakan, Mira melihat biaya nyata dari setiap pintu yang dipaksa terbuka.","body":"Jantung Lentara bukan batu atau mesin. Ia ruang kosong yang dipenuhi nama orang-orang yang pernah menyeberang. Setiap nama menyala ketika seseorang di salah satu dunia masih mengingat pemiliknya. Nama Mira berkedip di dekat nama ibunya. Tavi memanggil dari tepi retakan, suaranya terputus oleh angin yang membawa serpihan jam.\n\nMira dapat menyalurkan cahaya semua nama yang masih diingat untuk menjahit langit bersama, atau mengambil tugas menjaga nama-nama yang hampir padam sampai kedua dunia siap membuat perjanjian baru. Tidak ada jalan tanpa kehilangan. Tetapi untuk pertama kalinya ia tahu persis kehilangan siapa yang harus diminta izin. Ia memegang peta yang kini tidak lagi menggambar satu garis, melainkan ruang kosong tempat orang-orang dapat menulis pilihannya sendiri.","choices":[["fajar-untuk-semua","Satukan ingatan yang diberikan sukarela"],["nama-yang-tinggal","Tinggal sebagai penjaga nama"]]},{"number":31,"key":"fajar-untuk-semua","title":"Fajar untuk Semua","synopsis":"Lentara dan Bumi memilih membangun jembatan dengan persetujuan kedua sisi.","body":"Mira meletakkan kunci di tengah aula. Dari kota, desa, terminal, dan ruang detik nol, orang-orang datang membawa ingatan yang mereka rela bagikan. Tidak semua setuju membuka pintu segera. Karena itu pintu pertama justru dibuat dengan gagang di kedua sisinya: ia baru bergerak jika dua tangan memutarnya bersama. Ruun menjahit langit dengan benang dari perjanjian yang dibacakan keras-keras, sehingga tak seorang pun dapat diam-diam mengambilnya lagi.\n\nSaat fajar menyentuh Lentara, retakan berubah menjadi garis perak yang masih terlihat. Ia menjadi pengingat, bukan luka yang disembunyikan. Mira pulang menemui ibunya, lalu kembali beberapa bulan kemudian dengan kotak kue baru untuk Tavi. Perjalanan itu memerlukan izin, kesabaran, dan dua tiket. Mira menyukai aturan tersebut. Setiap kali pintu terbuka, kedua dunia tahu siapa yang sedang mereka sambut.","choices":[]},{"number":32,"key":"rumah-dua-pintu","title":"Rumah dengan Dua Pintu","synopsis":"Mira pulang tanpa menutup kemungkinan untuk kembali dengan aman.","body":"Ibunya membuka pintu apartemen sebelum Mira sempat mengetuk. Mereka berpelukan lama, tanpa meminta penjelasan yang mustahil diberikan dalam satu napas. Di atas meja, Mira menggambar dua lingkaran dan sebuah garis di antaranya. Ibunya mengenali gambar itu dari masa kecilnya; ia pernah melihat nenek buyut Mira membuat kunci yang sama, lalu memilih melupakannya agar pintu tidak dicari orang sembarangan.\n\nBersama Damar, mereka memperbaiki mesin lift dari sisi Bumi. Di Lentara, Tavi dan Ruun membangun pasangan kuncinya. Pintu itu tidak selalu terbuka. Setiap perjalanan diumumkan, disetujui, dan dicatat oleh kedua penjaga. Mira melanjutkan hidupnya di kota asal, tetapi menyimpan tiket bercap bulan di dompet. Ketika hujan jatuh ke atas pada suatu sore, ia tersenyum. Ada dua tempat yang kini dapat ia sebut rumah.","choices":[]},{"number":33,"key":"nama-yang-tinggal","title":"Nama yang Tinggal","synopsis":"Mira memilih tinggal sementara untuk menjaga ingatan yang hampir hilang.","body":"Mira menulis nama pertama pada dinding jantung Lentara, lalu nama kedua. Setiap nama membuat satu lampu kecil menyala di kejauhan. Ia tidak menjadi tahanan retakan; ia menjadi penjaga yang bisa digantikan ketika orang lain siap. Tavi membawakan makanan, Ruun mengajarinya menjahit benang langit, dan Aven membuka arsip agar keluarga dari kedua dunia dapat mencari mereka yang pernah hilang.\n\nDi Bumi, ibunya menerima satu surat melalui lift setiap bulan. Mira menceritakan cuaca yang belum punya nama dan anak-anak desa yang kembali mengingat lagu. Ia juga menulis bahwa ia rindu. Suatu hari, ketika cukup banyak nama pulih dan kedua dunia berani saling bertanya, Mira akan membuka pintu lagi. Sampai saat itu, ia menjaga lampu-lampu kecil tersebut agar tak satu pun pulang ke dunia yang sudah melupakan mereka.","choices":[]}]}$novel_data$::jsonb;
  v_story uuid;
  v_graph jsonb;
  v_episodes jsonb;
  v_nodes jsonb;
  v_choices jsonb;
  v_ep1 uuid := gen_random_uuid();
  v_ep2 uuid := gen_random_uuid();
  v_ep3 uuid := gen_random_uuid();
  v_ep4 uuid := gen_random_uuid();
  v_ep5 uuid := gen_random_uuid();
begin
  if exists(select 1 from public.stories where slug=v_data->>'slug') then
    raise notice 'Web Novel seed already exists; left unchanged';
    return;
  end if;
  insert into public.stories(slug,title,tagline,description,default_format,status,visibility,published_at,genres,tags)
  values(v_data->>'slug',v_data->>'title',v_data->>'tagline',v_data->>'description','web_novel','published','public',now(),
    array['fantasi','petualangan'],array['isekai','dunia lain','pilihan bercabang'])
  returning id into v_story;

  insert into public.story_nodes(story_id,node_key,title,synopsis,node_type,is_start,status,sequence_hint,unlock_cost)
  select v_story,c->>'key',c->>'title',c->>'synopsis',
    case when jsonb_array_length(c->'choices')=0 then 'ending' else 'episode' end,
    (c->>'number')::integer=1,'published',(c->>'number')::integer,
    case when (c->>'number')::integer=1 then 0 else 5 end
  from jsonb_array_elements(v_data->'chapters') c order by (c->>'number')::integer;

  insert into public.story_node_prose_drafts(node_id,body)
  select n.id,c->>'body' from jsonb_array_elements(v_data->'chapters') c
  join public.story_nodes n on n.story_id=v_story and n.node_key=c->>'key';
  insert into public.story_node_prose_publications(node_id,body)
  select n.id,c->>'body' from jsonb_array_elements(v_data->'chapters') c
  join public.story_nodes n on n.story_id=v_story and n.node_key=c->>'key';

  insert into public.story_choices(story_id,node_id,next_node_id,label,sort_order)
  select v_story,source.id,target.id,choice.value->>1,choice.position::integer
  from jsonb_array_elements(v_data->'chapters') chapter
  join public.story_nodes source on source.story_id=v_story and source.node_key=chapter->>'key'
  cross join lateral jsonb_array_elements(chapter->'choices') with ordinality as choice(value,position)
  join public.story_nodes target on target.story_id=v_story and target.node_key=choice.value->>0;

  v_episodes := jsonb_build_array(
    jsonb_build_object('id',v_ep1,'title',v_data->'episodes'->>0,'sortOrder',1),
    jsonb_build_object('id',v_ep2,'title',v_data->'episodes'->>1,'sortOrder',2),
    jsonb_build_object('id',v_ep3,'title',v_data->'episodes'->>2,'sortOrder',3),
    jsonb_build_object('id',v_ep4,'title',v_data->'episodes'->>3,'sortOrder',4),
    jsonb_build_object('id',v_ep5,'title',v_data->'episodes'->>4,'sortOrder',5));
  select jsonb_agg(jsonb_build_object('id',n.id,'key',n.node_key,'title',n.title,
    'synopsis',coalesce(n.synopsis,''),'type',n.node_type,'start',n.is_start,
    'episodeId',case when n.sequence_hint<=6 then v_ep1 when n.sequence_hint<=12 then v_ep2
      when n.sequence_hint<=18 then v_ep3 when n.sequence_hint<=25 then v_ep4 else v_ep5 end,
    'x',null,'y',null,'tags','[]'::jsonb,'notes','') order by n.sequence_hint)
  into v_nodes from public.story_nodes n where n.story_id=v_story;
  select jsonb_agg(jsonb_build_object('id',c.id,'source',c.node_id,'target',c.next_node_id,
    'label',c.label,'description','','sortOrder',c.sort_order,'color','blue',
    'condition','{}'::jsonb) order by n.sequence_hint,c.sort_order)
  into v_choices from public.story_choices c join public.story_nodes n on n.id=c.node_id
  where c.story_id=v_story;
  v_graph := jsonb_build_object('episodes',v_episodes,'nodes',v_nodes,'choices',v_choices);
  insert into public.studio_graph_drafts(story_id,version,publication_version,graph)
  values(v_story,1,0,v_graph);
  update public.studio_graph_drafts set publication_version=1 where story_id=v_story;
  insert into public.studio_graph_publications(story_id,version,graph)
  values(v_story,1,v_graph);
end $novel_seed$;
